SELECT continuous_days FROM tb_user_sign_statistics 
WHERE user_id = #{userId}
LIMIT 1

SELECT * FROM tb_user_sign_in 
WHERE user_id = #{userId} 
AND sign_date BETWEEN #{startDate} AND #{endDate}
AND status = 1
ORDER BY sign_date DESC

SELECT * FROM tb_user_sign_in WHERE user_id = #{userId} AND status = 1
ORDER BY ${orderField}
ASC DESC DESC
ORDER BY sign_date DESC
LIMIT #{offset}, #{limit}
